def Binary_Search(Data , low , high , item):
    if low <= high:
        M = (low+high)//2
        if Data[M]==item:
            return M
        elif item < Data[M]:
            high = M - 1
            return Binary_Search(Data ,low, high , item)
        else:
            low = M + 1 
            return Binary_Search(Data , low , high , item)
