SOLUTION FOUND!
It was easier than I thought
    public List<BadgeDTO> CheckBadgesInRestaurant(string restaurantId)
    {
        return _context.Badges
            .AsNoTracking()
            .Select(b => new BadgeDTO()
            {
                Id = b.Id,
                Name = b.Name,
                Check = _context.RestaurantBadges
                    .AsNoTracking()
                    .Where(br => br.BadgeId == b.Id && br.RestaurantId == restaurantId)
                    .Any()
            }).OrderBy(b => b.Id)
            .ToList());
    }

